import{_ as r,o as t,c as o,ag as a}from"./chunks/framework.cyF4XceO.js";const u=JSON.parse('{"title":"Use Takoform Provider","description":"","frontmatter":{},"headers":[],"relativePath":"docs/index.md","filePath":"docs/index.md"}'),s={name:"docs/index.md"};function i(d,e,n,c,h,p){return t(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="use-takoform-provider" tabindex="-1">Use Takoform Provider <a class="header-anchor" href="#use-takoform-provider" aria-label="Permalink to &quot;Use Takoform Provider&quot;">​</a></h1><p>Manage exact Takoform Forms from Terraform or OpenTofu. A compatible Host provides the endpoint, Space, authentication, and service implementation.</p><h2 id="choose-your-version" tabindex="-1">Choose your version <a class="header-anchor" href="#choose-your-version" aria-label="Permalink to &quot;Choose your version&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Use</th><th>Provider</th><th>Host API</th><th>Resource mappings</th></tr></thead><tbody><tr><td>Current source target / candidate</td><td><strong>5.0.0</strong></td><td><code>forms.takoform.com/v2</code></td><td>13 exact Edge Form URLs</td></tr><tr><td>Deprecated Registry release</td><td><strong>4.1.0</strong></td><td><code>forms.takoform.com/v1</code></td><td>17 Edge Forms</td></tr></tbody></table><p>The default source-built Provider uses Host API v2; the v1 client is deprecated and unsupported by that entrypoint. The <a href="https://github.com/tako0614/terraform-provider-takoform/blob/main/release/provider-release-identities.json" target="_blank" rel="noreferrer">release identity ledger</a> records the verified 4.1.0 Registry publication. Provider 5.0.0 is a source target, not proven Registry-published: check the live listing and exact-version readback before installation. <strong>Provider 4 state is not automatically translated to Provider 5.</strong></p><h2 id="current-path-evaluate-provider-5-source" tabindex="-1">Current path: evaluate Provider 5 source <a class="header-anchor" href="#current-path-evaluate-provider-5-source" aria-label="Permalink to &quot;Current path: evaluate Provider 5 source&quot;">​</a></h2><p>Use the <a href="/docs/provider-host-api-v2-source.html">Provider 5 consumer reference</a> for the current v2 schema, thirteen mappings, local or remote private-store custody, import, and lifecycle boundaries. The Host must independently support <code>forms.takoform.com/v2</code> and each exact Form URL.</p><h2 id="deprecated-published-provider-4-1-0" tabindex="-1">Deprecated published Provider 4.1.0 <a class="header-anchor" href="#deprecated-published-provider-4-1-0" aria-label="Permalink to &quot;Deprecated published Provider 4.1.0&quot;">​</a></h2><p>The <a href="/docs/getting-started.html">legacy getting-started guide</a> covers Registry-published Provider 4.1.0 / Host API v1 for retained workspaces. This release is unsupported by the default Provider 5 entrypoint.</p><h2 id="resource-reference" tabindex="-1">Resource reference <a class="header-anchor" href="#resource-reference" aria-label="Permalink to &quot;Resource reference {#resource-reference}&quot;">​</a></h2><p>The <a href="/docs/reference.html#resource-reference">Provider reference</a> and its seventeen resource pages describe deprecated <strong>Provider 4.1.0 / Host API v1</strong>. Use the Provider 5 reference above for the current source-v2 schema and Form URLs.</p><p>For migration and release evidence, see <a href="/docs/versions.html">Versions and compatibility</a>, the <a href="/release/migrations/v3-to-v4.html">v3-to-v4 migration guide</a>, and <a href="/conformance/">Conformance</a>. For provider-neutral API contracts, see the <a href="https://takoform.com/en/host-api/" target="_blank" rel="noreferrer">Host API documentation</a>.</p><p>For an AWS resource alongside Takoform, see <a href="/examples/native-provider-composition/main.tf">native provider composition</a>. Each Provider keeps its own source, credentials, and state.</p>',13)])])}const m=r(s,[["render",i]]);export{u as __pageData,m as default};
